import boto3

def get_bedrock_client(region_name="us-east-1"):
    return boto3.client("bedrock-runtime", region_name=region_name)

import json

def create_titan_text_embedding_payload(text):
    return json.dumps({"inputText": text})

def parse_titan_text_embedding_response(response_body):
    return json.loads(response_body.read())["embedding"]

def create_titan_multimodal_embedding_payload(text_segment):
    return json.dumps({"text": text_segment})

def parse_titan_multimodal_embedding_response(response_body):
    return json.loads(response_body.read())

import json

from embeddings_client import get_bedrock_client
from embeddings_models import create_titan_text_embedding_payload, parse_titan_text_embedding_response


def embed_batch(texts, config=None):
    config = config or {}
    client = get_bedrock_client(config.get("region", "us-east-1"))
    embeddings = []
    for text in texts:
        response = client.invoke_model(
            modelId="amazon.titan-embed-text-v2:0",
            body=create_titan_text_embedding_payload(text),
            contentType="application/json",
            accept="application/json",
        )
        stream = response["body"]
        try:
            embeddings.append(parse_titan_text_embedding_response(stream))
        finally:
            stream.close()
    return {"embeddings": embeddings}

import numpy as np

def embedding_job_summary(embedding_results):
    if not embedding_results:
        return {"total_embeddings": 0, "average_embedding": None}

    total_embeddings = len(embedding_results)

    # Assuming embedding_results is a list of dictionaries, each with an 'embedding' key
    # or directly a list of embedding vectors
    embeddings_data = []
    for res in embedding_results:
        if isinstance(res, dict) and "embedding" in res:
            embeddings_data.append(res["embedding"])
        elif isinstance(res, list):
            embeddings_data.append(res)
        else:
            # Handle cases where the input might just be the embedding vector itself
            embeddings_data.append(res)

    if not embeddings_data:
        return {"total_embeddings": 0, "average_embedding": None}

    # Convert to numpy array for mean calculation
    embeddings_np = np.array(embeddings_data)
    average_embedding = np.mean(embeddings_np, axis=0).tolist()

    return {"total_embeddings": total_embeddings, "average_embedding": average_embedding}

import boto3

def multilingual_query_translate(query_text, target_language_code, source_language_code="auto", config=None):
    config = config or {}
    client = boto3.client("translate", region_name=config.get("region", "us-east-1"))

    if source_language_code == "auto":
        response = client.translate_text(
            Text=query_text,
            TargetLanguageCode=target_language_code,
        )
    else:
        response = client.translate_text(
            Text=query_text,
            SourceLanguageCode=source_language_code,
            TargetLanguageCode=target_language_code,
        )

    translated_text = response["TranslatedText"]
    return {"translated_query": translated_text, "source_language": response.get("SourceLanguageCode", source_language_code)}

import boto3
from botocore.exceptions import ClientError

def retrieval_audio_brief(text_to_speak, voice_id="Joanna", output_format="mp3", config=None):
    config = config or {}
    client = boto3.client("polly", region_name=config.get("region", "us-east-1"))

    try:
        response = client.synthesize_speech(
            Text=text_to_speak,
            OutputFormat=output_format,
            VoiceId=voice_id,
        )
    except ClientError as e:
        print(f"Error synthesizing speech: {e}")
        return {"audio_stream": None, "error": str(e)}

    if "AudioStream" in response:
        # The AudioStream is a botocore.response.StreamingBody object
        # For this example, we'll return it directly. In a real application,
        # you would likely save it to a file or stream it to a client.
        return {"audio_stream": response["AudioStream"].read(), "output_format": output_format}
    else:
        return {"audio_stream": None, "error": "No audio stream in response"}
